package main
import("fmt";"os";"path/filepath";"sort";"strings")
type rec struct{p string;s int64};func main(){if len(os.Args)<2||os.Args[1]=="--help"{fmt.Println("Usage: dir-summary DIRECTORY [TOP]");if len(os.Args)<2{os.Exit(2)};return};root:=os.Args[1];top:=10;if len(os.Args)>2{fmt.Sscan(os.Args[2],&top)};var files,dirs int;var bytes int64;var largest []rec;ext:=map[string]int{};err:=filepath.Walk(root,func(p string,i os.FileInfo,e error)error{if e!=nil{return nil};if i.IsDir(){dirs++;return nil};files++;bytes+=i.Size();largest=append(largest,rec{p,i.Size()});x:=strings.ToLower(filepath.Ext(i.Name()));if x==""{x="[none]"};ext[x]++;return nil});if err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)};sort.Slice(largest,func(i,j int)bool{return largest[i].s>largest[j].s});fmt.Printf("files=%d\ndirectories=%d\nbytes=%d\n",files,dirs,bytes);fmt.Println("largest:");for i:=0;i<top&&i<len(largest);i++{fmt.Printf("%d\t%s\n",largest[i].s,largest[i].p)};type kv struct{k string;v int};var xs []kv;for k,v:=range ext{xs=append(xs,kv{k,v})};sort.Slice(xs,func(i,j int)bool{return xs[i].v>xs[j].v});fmt.Println("extensions:");for i,x:=range xs{if i>=20{break};fmt.Printf("%d\t%s\n",x.v,x.k)}}
